def gen(rng):
    LO, HI = -2**31, 2**31 - 1
    def shape(n, kind):
        left = [-1] * n
        right = [-1] * n
        if kind == 'random':
            free = [(0, 0), (0, 1)]
            for i in range(1, n):
                j = rng.randrange(len(free))
                free[j], free[-1] = free[-1], free[j]
                p, side = free.pop()
                if side == 0:
                    left[p] = i
                else:
                    right[p] = i
                free.append((i, 0))
                free.append((i, 1))
        elif kind == 'left':
            for i in range(1, n):
                left[i - 1] = i
        elif kind == 'right':
            for i in range(1, n):
                right[i - 1] = i
        elif kind == 'zigzag':
            for i in range(1, n):
                if i % 2:
                    left[i - 1] = i
                else:
                    right[i - 1] = i
        else:
            for i in range(1, n):
                p = (i - 1) // 2
                if i % 2:
                    left[p] = i
                else:
                    right[p] = i
        return left, right
    def inorder(left, right):
        res, st, u = [], [], 0
        while st or u != -1:
            while u != -1:
                st.append(u)
                u = left[u]
            u = st.pop()
            res.append(u)
            u = right[u]
        return res
    def serialize(vals, left, right):
        out = [str(vals[0])]
        q = [0]
        qi = 0
        while qi < len(q):
            u = q[qi]
            qi += 1
            for c in (left[u], right[u]):
                if c == -1:
                    out.append('null')
                else:
                    out.append(str(vals[c]))
                    q.append(c)
        while out and out[-1] == 'null':
            out.pop()
        return ' '.join(out)
    def make(n, kind, mutation, span=None):
        left, right = shape(n, kind)
        order = inorder(left, right)
        if span is None:
            vs = sorted(rng.sample(range(LO, HI + 1), n)) if n > 0 else []
        else:
            vs = sorted(rng.sample(range(-span, span + 1), n))
        vals = [0] * n
        for pos, u in enumerate(order):
            vals[u] = vs[pos]
        if mutation == 'swap' and n >= 2:
            i = rng.randrange(n)
            j = rng.randrange(n)
            while j == i:
                j = rng.randrange(n)
            a, b = order[i], order[j]
            vals[a], vals[b] = vals[b], vals[a]
        elif mutation == 'dup' and n >= 2:
            i = rng.randrange(n - 1)
            vals[order[i]] = vals[order[i + 1]]
        elif mutation == 'bump':
            u = rng.randrange(n)
            vals[u] = rng.randint(-span if span else LO, span if span else HI)
        return serialize(vals, left, right)
    tests = [
